#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

prompt_value() {
  local variable="$1" prompt="$2" default_value="${3:-}" input=""
  if [[ -n "$default_value" ]]; then
    read -e -r -p "  ${BOLD}${prompt}${RESET} [${default_value}] " input || true
    [[ -z "$input" ]] && input="$default_value"
  else
    read -e -r -p "  ${BOLD}${prompt}${RESET} " input || true
  fi
  printf -v "$variable" '%s' "$input"
}

record_value() {
  local label="$1" value="$2"
  value="${value//$'\r'/}"
  value="${value//$'\n'/ }"
  printf -- '- **%s:** %s\n' "$label" "${value:-Not recorded}" >> "$RECORD_PATH"
}

record_result() {
  local title="$1" result="" notes=""
  while [[ ! "$result" =~ ^(PASS|FAIL|BLOCKED)$ ]]; do
    prompt_value result "Result for ${title} (PASS, FAIL, or BLOCKED):"
    result="${result^^}"
  done
  prompt_value notes "Concise evidence summary (no secrets, private addresses, or raw payloads):"
  {
    printf '\n### %s\n\n' "$title"
    printf -- '- **Result:** %s\n' "$result"
    printf -- '- **Evidence summary:** %s\n' "${notes:-Not recorded}"
  } >> "$RECORD_PATH"
}

run_wizard() {

TOTAL_STAGES=8

banner "Awair Element physical qualification"

stage "Create the private qualification record"
say "This procedure records observations from real hardware; it does not create or publish evidence for you."
warn "Keep the record private until addresses, identifiers, payloads, logs, and topology have been reviewed and redacted."
local script_root template_path default_record
script_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
template_path="$script_root/docs/hardware-qualification-template.md"
default_record="$PWD/awair-hardware-qualification-$(date -u +%Y%m%dT%H%M%SZ).md"
while true; do
  prompt_value RECORD_PATH "Output record path:" "$default_record"
  if [[ ! -e "$RECORD_PATH" ]]; then break; fi
  warn "that path already exists; choose a new path so existing evidence is not overwritten"
done
mkdir -p -- "$(dirname -- "$RECORD_PATH")"
cp -- "$template_path" "$RECORD_PATH"
chmod 600 "$RECORD_PATH"
local tester test_date image_ref image_digest source_revision host_summary device_model firmware network_summary
prompt_value tester "Tester or lab name:"
prompt_value test_date "Qualification start (UTC):" "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
prompt_value image_ref "Exact container image reference:"
prompt_value image_digest "Resolved image digest (sha256:...):"
prompt_value source_revision "Source revision:"
prompt_value host_summary "Host OS and architecture:"
prompt_value device_model "Awair model and hardware revision:"
prompt_value firmware "Awair firmware version:"
prompt_value network_summary "Redacted network summary (for example, same VLAN; no public ingress):"
{
  printf '\n## Wizard-captured run\n\n'
} >> "$RECORD_PATH"
record_value "Tester/lab" "$tester"
record_value "Started (UTC)" "$test_date"
record_value "Image reference" "$image_ref"
record_value "Image digest" "$image_digest"
record_value "Source revision" "$source_revision"
record_value "Host" "$host_summary"
record_value "Device" "$device_model"
record_value "Firmware" "$firmware"
record_value "Redacted network summary" "$network_summary"
[[ "$image_digest" =~ ^sha256:[0-9a-fA-F]{64}$ ]] || warn "the digest is not in sha256:<64 hex characters> form; verify it before deciding"

stage "Confirm device and network prerequisites"
step "Use a non-production Awair Element on the same trusted LAN as the qualification host."
step "Enable the device's Local API using Awair's supported user workflow; do not enter account credentials here."
step "Confirm the LAN permits mDNS and direct local HTTP, has no public ingress, and does not use a transparent proxy for the device."
step "Confirm you can safely restart or isolate the device and restore its original DHCP/network state."
record_result "Preconditions and Local API enablement"

stage "Verify mDNS identity and local addressing"
step "Observe mDNS with avahi-browse, dns-sd, or an equivalent LAN tool."
step "Verify an _http._tcp.local., _awair._tcp.local., or _hap._tcp.local. service whose first label is AWAIR-ELEM-* exactly identifies this device."
step "Verify every resolved address is private/link-local and port 80 serves GET /air-data/latest without a redirect."
step "Record only the identity pattern, service types, address class, and observation method; keep exact names and addresses private."
record_result "mDNS identity and local-only resolution"

stage "Run the exact constrained image"
say "Resolve and inspect the image before launch; the digest in the record must match the image actually run."
step "Export a fresh local-only PIPHI_INTEGRATION_INTERNAL_TOKEN in your shell. Do not paste it into this wizard or the record."
step "Run the image with host networking for mDNS, UID/GID 10001, a read-only root filesystem, writable tmpfs mounts at /tmp and /var/lib/piphi, all capabilities dropped, and no-new-privileges."
note 'Example flags: --network host --user 10001:10001 --read-only --tmpfs /tmp --tmpfs /var/lib/piphi --cap-drop ALL --security-opt no-new-privileges'
step "Verify GET http://127.0.0.1:3665/health succeeds, protected routes reject a missing token, and the container reports the expected version."
step "Keep the container name and exact launch command in the private lab record; do not reuse an existing container name."
record_result "Constrained container launch and authentication"

stage "Compare Local API and integration telemetry"
step "Make one direct read-only GET /air-data/latest request with proxy bypass enabled and retain the raw response only in private evidence."
step "Call the authenticated /discover endpoint and verify it returns this AWAIR-ELEM-* device only after a successful Local API probe."
step "Apply a test config with the observed identity/address and a polling interval of at least 10 seconds, then read authenticated /state."
step "Compare field presence, numeric types, units, timestamp handling, and values. The integration may omit unknown fields but must not invent readings."
step "Exercise the refresh command once and verify that it performs only another GET of /air-data/latest."
record_result "Firmware payload and telemetry comparison"

stage "Exercise restart, outage, and address change"
step "Restart the integration container and verify the accepted config/state recovery behavior against the record template."
step "Temporarily isolate or restart the Awair, then verify stale last-good state, unavailable status, bounded retry, and recovery after connectivity returns."
step "In the lab DHCP controls, change the device address without changing its AWAIR-ELEM-* identity. Observe discovery and configured-device behavior; do not assume automatic migration."
step "Restore the original network state and verify normal polling resumes. Record timings and any manual reconfiguration required."
record_result "Restart, outage, recovery, and DHCP address change"

stage "Review privacy and read-only behavior"
step "Review container logs, runtime diagnostics, and any private packet capture for leaked tokens, exact device addresses/names, raw payloads, or customer topology."
step "Verify device traffic is local and consists only of GET /air-data/latest; reject redirects, proxy use, cloud requests, and all write/control methods."
step "Verify diagnostics contain aggregate counts only and the runtime remains non-root with a read-only application/root filesystem."
step "Redact copies intended for sharing; never publish packet captures, credentials, private addresses, or unreviewed logs."
record_result "Privacy, network egress, and read-only behavior"

stage "Record the qualification decision"
say "A PASS applies only to the exact image digest, source revision, firmware, hardware, and network conditions in this record."
step "After retaining required private evidence, stop and remove only the dedicated qualification container, clear the token from your shell, and leave shared images/volumes untouched."
local decision blockers follow_up ended_at
prompt_value decision "Final decision (PASS, FAIL, or BLOCKED):"
decision="${decision^^}"
while [[ ! "$decision" =~ ^(PASS|FAIL|BLOCKED)$ ]]; do
  prompt_value decision "Enter PASS, FAIL, or BLOCKED:"
  decision="${decision^^}"
done
prompt_value blockers "Blockers or deviations (write None only if verified):"
prompt_value follow_up "Required follow-up:"
ended_at=$(date -u +%Y-%m-%dT%H:%M:%SZ)
{
  printf '\n## Wizard decision\n\n'
  printf -- '- **Decision:** %s\n' "$decision"
  printf -- '- **Completed (UTC):** %s\n' "$ended_at"
  printf -- '- **Blockers/deviations:** %s\n' "${blockers:-Not recorded}"
  printf -- '- **Required follow-up:** %s\n' "${follow_up:-Not recorded}"
  printf -- '- **Long-duration polling stability:** Not assessed; soak testing was excluded from this qualification\n'
  printf -- '- **Publication/governance:** Not performed by this wizard\n'
} >> "$RECORD_PATH"
say "Record written to: $RECORD_PATH"
warn "Completion does not merge, publish, synchronize a registry, or promote governance. Review and redact before sharing."

finish
}

run_wizard "$@"; exit
